CREATE EXTENSION IF NOT EXISTS postgis;

CREATE SCHEMA IF NOT EXISTS menara_telekomunikasi;

CREATE TABLE IF NOT EXISTS menara_telekomunikasi.menara (
    id BIGINT PRIMARY KEY,
    kecamatan TEXT,
    kelurahan TEXT,
    nama_perusahaan TEXT,
    lokasi_menara TEXT,
    latitude DOUBLE PRECISION,
    longitude DOUBLE PRECISION,
    tinggi_m DOUBLE PRECISION,
    struktur_tower TEXT,
    penempatan TEXT,
    status_imb TEXT,
    nomor_imb TEXT,
    keterangan TEXT,
    catatan_kualitas TEXT,
    geom geometry(Point, 4326)
);


UPDATE menara_telekomunikasi.menara
SET geom = ST_SetSRID(
    ST_MakePoint(longitude, latitude),
    4326
)
WHERE latitude BETWEEN -90 AND 90
  AND longitude BETWEEN -180 AND 180;

CREATE INDEX IF NOT EXISTS idx_menara_geom
ON menara_telekomunikasi.menara
USING GIST (geom);